from typing import List

def max_score(grid: List[List[int]]) -> int:
    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.
    """
    rows = len(grid)
    if rows == 0:
        return 0
    cols = len(grid[0])

    memo = {}

    def solve(row_idx, used_values):
        state = (row_idx, used_values)
        if state in memo:
            return memo[state]

        if row_idx == rows:
            return 0

        # Option 1: Don't select any cell in this row
        res = solve(row_idx + 1, used_values)

        # Option 2: Select one cell in this row
        for c in range(cols):
            val = grid[row_idx][c]
            if val not in used_values:
                # Create a new frozenset for the next state
                new_used = used_values | {val}
                res = max(res, val + solve(row_idx + 1, new_used))

        memo[state] = res
        return res

    # Use frozenset for the set of used values to make it hashable for memoization
    return solve(0, frozenset())
